1. Validates that `name` is `policy_file` (otherwise error with exit code 1)
2. Validates that the `path` exists (otherwise error with exit code 1)
3. For version `2.0`: loads and validates a policy file, printing success message with parsed content
4. For version `3.0`: loads and validates a v3.0 policy file, printing success message with parsed content
5. Handles invalid keywords with appropriate error messages

```python
@cli.command(cls=SafetyCLILegacyCommand, utility_command=True)
@click.option("--path", default=".safety-policy.yml", help="Path where the generated file will be saved. Default: current directory")
@click.argument('name')
@click.argument('version', required=False)
@click.pass_context
def validate(ctx, name, version, path):
    """Validate a Safety CLI policy file

    NAME is the name of the file type to validate. Valid values are: policy_file
    """
    if name != 'policy_file':
        click.secho(
            f'This Safety version only supports "policy_file" validation. "{name}" is not supported.',
            fg='red', file=sys.stderr
        )
        sys.exit(EXIT_CODE_FAILURE)

    p = Path(path)
    if not p.exists():
        click.secho(f'The path "{path}" does not exist.', fg='red', file=sys.stderr)
        sys.exit(EXIT_CODE_FAILURE)

    LOG.info('Running validate %s', name)

    # Determine version - default to '2.0' if not specified
    policy_version = version if version else '2.0'

    if policy_version == '3.0':
        # Handle v3.0 policy file validation
        try:
            config = ConfigModel.parse_policy_file(p)
            msg = "The Safety policy (3.0) file (Used for scan and system-scan commands) was successfully parsed with the following values:\n"
            click.secho(msg, nl=False)
            click.secho(json.dumps(json.loads(config.json()), indent=2))
        except Exception as e:
            click.secho(
                f'Unable to load the Safety Policy file ("{path}"), this command only supports version 3.0, details: {e}',
                fg='red', file=sys.stderr
            )
            sys.exit(EXIT_CODE_FAILURE)
    else:
        # Handle v2.0 policy file validation
        try:
            policy_file = SafetyPolicyFile().convert(path, None, None)
            msg = "The Safety policy file (Valid only for the check command) was successfully parsed with the following values:\n"
            click.secho(msg, nl=False)
            click.secho(json.dumps(policy_file, indent=2))
        except click.exceptions.BadParameter as e:
            click.secho(
                f'Unable to load the Safety Policy file "{path}".\n{e.format_message()}',
                fg='red', file=sys.stderr
            )
            sys.exit(EXIT_CODE_FAILURE)
        except Exception as e:
            click.secho(
                f'Unable to load the Safety Policy file "{path}".\n{str(e)}',
                fg='red', file=sys.stderr
            )
            sys.exit(EXIT_CODE_FAILURE)
